type ChangeEventBuilder struct {
	Arena              TableArena
	Main               TableWorker
	root               TableRef
	region, allocation []byte
}

func (b *ChangeEventBuilder) Init(allocator ...TableAllocator) bool {
	if b.region != nil || !b.Arena.Init(allocator...) {
		return false
	}
	b.Main = TableWorker{Arena: &b.Arena}
	p, ref := b.Main.Alloc(int64(unsafe.Sizeof(ChangeEvent{})))
	b.root = ref
	if p == nil {
		b.Arena.Shutdown()
		b.root = 0
		return false
	}
	ChangeEventReset((*ChangeEvent)(p))
	return true
}
func (b *ChangeEventBuilder) GetRoot() *ChangeEvent {
	if b.Arena.Locked {
		return nil
	}
	return (*ChangeEvent)(b.Arena.At(b.root))
}
func (b *ChangeEventBuilder) AsConst() *ChangeEvent {
	if len(b.region) == 0 {
		return nil
	}
	return (*ChangeEvent)(unsafe.Pointer(&b.region[0]))
}
func (b *ChangeEventBuilder) Region() []byte { return b.region }
