func CellSaveMessageBody(w *TableMessageWriter, value *Cell) bool {
	{
		if value.RowLength < 0 || value.RowLength > 256 {
			return false
		}
		if value.RowLength > 0 {
			w.Put(1, TableMessageRefBitsHere)
			if value.RowLength < 0 || value.RowLength > 256 {
				return false
			}
			w.Put(uint64(value.RowLength), 9)
			w.Raw(value.Row[:value.RowLength])
		}
	}
	{
		if value.ColumnLength < 0 || value.ColumnLength > 128 {
			return false
		}
		if value.ColumnLength > 0 {
			w.Put(2, TableMessageRefBitsHere)
			if value.ColumnLength < 0 || value.ColumnLength > 128 {
				return false
			}
			w.Put(uint64(value.ColumnLength), 8)
			w.Raw(value.Column[:value.ColumnLength])
		}
	}
	{
		if value.TextLength < 0 || value.TextLength > 256 {
			return false
		}
		if value.TextLength > 0 {
			w.Put(3, TableMessageRefBitsHere)
			if value.TextLength < 0 || value.TextLength > 256 {
				return false
			}
			w.Put(uint64(value.TextLength), 9)
			w.Raw(value.Text[:value.TextLength])
		}
	}
	w.Put(0, TableMessageRefBitsHere)
	return !w.Overflow
}
func CellMeasureMessages(values []*Cell, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Measuring: true}}
	for _, value := range values {
		if value == nil || !CellSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
func CellSaveMessages(values []*Cell, buffer []byte, report *TableReport) int64 {
	if len(values) < 1 || len(values) > TableMessageBatchMax {
		if report != nil {
			tableMessageRefuse(report, "batch_too_large")
		}
		return -1
	}
	if len(buffer) < 2 {
		return -1
	}
	buffer[0] = 2
	buffer[1] = byte(len(values) - 1)
	w := TableMessageWriter{TableBitWriter: TableBitWriter{Buffer: buffer[2:]}}
	for _, value := range values {
		if value == nil || !CellSaveMessageBody(&w, value) {
			return -1
		}
	}
	w.Align()
	if w.Overflow {
		return -1
	}
	return 2 + w.Bits/8
}
