func CellSetLoadMessageBodyRetain(r *TableRetainMessageReader, value *CellSet) bool {
	CellSetReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0x0c99365e92f7d2f2:
			{
				widened := false
				if entry.Shape.Kind != 14 || entry.Element.Kind != 13 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					base := &value.Cells
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok {
						r.Report.Malformed = true
						return false
					}
					if entry.Element.Kind == 6 && !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					element := TableMessageEntry{Shape: entry.Element}
					_ = element
					r.Retain.discard(r.Path, true, 0)
					keep := min(n, uint64(64))
					if keep < n {
						r.Report.Clamped++
					}
					walk := n
					if element.Shape.Bits >= 0 {
						walk = keep
					}
					for i := uint64(0); i < walk; i++ {
						var scratch Cell
						p := &scratch
						if i < keep {
							p = &base[i]
						}
						store := r.Retain
						if i >= keep {
							r.Retain = nil
						}
						{
							payload6 := r.Path
							r.Path = r.Path.step(0, uint32(i))
							if !CellLoadMessageBodyRetain(r, &(*p)) {
								return false
							}
							r.Path = payload6
						}
						r.Retain = store
					}
					if walk < n && !r.Bits.Skip(int64(n-walk)*element.Shape.Bits) {
						r.Report.Malformed = true
						return false
					}
					value.CellsCount = int32(keep)
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !r.capture(entry) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
