func (b *CellSetBuilder) Lock() bool {
	if b.Arena.Locked {
		return true
	}
	region, allocation, ok := tableRegionPack(unsafe.Pointer(b.GetRoot()), CellSetTableType(), &b.Arena)
	if !ok {
		return false
	}
	b.region = region
	b.allocation = allocation
	b.Arena.Shutdown()
	b.Arena.Locked = true
	return true
}
func (b *CellSetBuilder) Shutdown() {
	b.Arena.Shutdown()
	b.Arena.Allocator.free(b.allocation)
	b.region = nil
	b.allocation = nil
	b.root = 0
}

// StreamTransitionReset restores StreamTransition's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StreamTransitionReset(value *StreamTransition) {
	clear(value.State[:])
	value.StateLength = 0
	clear(value.Cause[:])
	value.CauseLength = 0
	value.Waiting = 0
	for i := range value.Owners {
		Name128Reset(&value.Owners[i])
	}
	value.OwnersCount = 0
}

