func CoordinatorDeliveryMeasureBodyRetain(value *CoordinatorDelivery, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !CoordinatorDeliverySaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func CoordinatorDeliverySaveBodyRetain(w *TableRetainWriter, value *CoordinatorDelivery) bool {
	if !CoordinatorDeliverySaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
