func PropWriteSave(value *PropWrite, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !PropWriteSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func PropWriteLoadBody(r *TableReader, value *PropWrite) bool {
	PropWriteReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Malformed = true
			return false
		}
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Malformed = true
			return false
		}
		kind := r.Get8()
		switch fieldID {
		case 0x6bcb6e85b78cf363: // table_name
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.TableName[:])
				value.TableNameLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 128 {
				keep = tableUtf8Clamp(sub.Buffer, 128)
				r.Report.Clamped++
			}
			clear(value.TableName[:])
			copy(value.TableName[:keep], sub.Buffer)
			value.TableNameLength = int32(keep)
		case 0xc4bcadba8e631b86: // name
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Name[:])
				value.NameLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 128 {
				keep = tableUtf8Clamp(sub.Buffer, 128)
				r.Report.Clamped++
			}
			clear(value.Name[:])
			copy(value.Name[:keep], sub.Buffer)
			value.NameLength = int32(keep)
		case 0x7ce4fd9430e80cea: // value
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Value[:])
				value.ValueLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 1024 {
				keep = tableUtf8Clamp(sub.Buffer, 1024)
				r.Report.Clamped++
			}
			clear(value.Value[:])
			copy(value.Value[:keep], sub.Buffer)
			value.ValueLength = int32(keep)
		case 0x5eade819487cb532: // was
			if kind != 12 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			sub, ok := r.Body()
			if !ok {
				r.Report.Malformed = true
				return false
			}
			if !tableUtf8Valid(sub.Buffer) {
				r.Report.Malformed = true
				clear(value.Was[:])
				value.WasLength = 0
				break
			}
			keep := int64(len(sub.Buffer))
			if keep > 1024 {
				keep = tableUtf8Clamp(sub.Buffer, 1024)
				r.Report.Clamped++
			}
			clear(value.Was[:])
			copy(value.Was[:keep], sub.Buffer)
			value.WasLength = int32(keep)
		case 0x32e6b0c4205a213e: // was_absent
			if kind != 1 {
				r.Report.KindMismatch++
				if !r.Skip(kind) {
					r.Report.Malformed = true
					return false
				}
				break
			}
			if !r.Has(1) {
				r.Report.Malformed = true
				return false
			}
			value.WasAbsent = r.Get8() != 0
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}

func PropWriteLoad(value *PropWrite, data []byte, report *TableReport) bool {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, verdict := tableOpen(data, report)
	report.Verdict = verdict
	report.Reason = ""
	if verdict == TableOpenRefused {
		report.Reason = "unsupported wire form"
		if len(data) > 0 && data[0] == 2 {
			report.Reason = "message form requires an announced vocabulary and a message reader"
		}
	}
	if verdict != TableOpenOk {
		PropWriteReset(value)
		if verdict == TableOpenDamaged {
			report.Malformed = true
		}
		return false
	}
	// The root read answers its own early end after the walk, not before it.
	// A body that returned at its zero reference left the cursor on the byte
	// after that reference. Every field leaves the cursor where skip would, so
	// r.Offset != len(r.Buffer) is the old EndsEarly on the true path.
	// Nothing is decoded on the damaged path: the value goes back to defaults
	// and the report goes back to what the caller handed in, so an early end
	// counts no unknown, no kind mismatch and no clamp — as when the framing
	// walk refused before the reader had seen one byte.
	before := *report
	if !PropWriteLoadBody(&r, value) {
		// The reading walk stops on rules the framing walk has no opinion about
		// — a reserved id in a file body is the one that matters — so a body
		// that stopped is still asked the framing question from the start of
		// the body, and a body whose framing ends early is damage whatever else
		// was wrong with it.
		probe := r
		probe.Offset = 0
		if probe.EndsEarly() {
			PropWriteReset(value)
			*report = before
			report.Malformed = true
			report.Verdict = TableOpenDamaged
			return false
		}
		report.Verdict = TableOpenBodyStopped
		return false
	}
	if r.Offset != int64(len(r.Buffer)) {
		PropWriteReset(value)
		*report = before
		report.Malformed = true
		report.Verdict = TableOpenDamaged
		return false
	}
	return true
}

