func PropWriteSaveBodyRetain(w *TableRetainWriter, value *PropWrite) bool {
	if !PropWriteSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func PropWriteSaveBodyFieldsRetain(w *TableRetainWriter, value *PropWrite) bool {
	{
		if value.TableNameLength < 0 || value.TableNameLength > 128 {
			return false
		}
		if value.TableNameLength > 0 {
			if ref := w.Ids.refAtHit(71, 0x6bcb6e85b78cf363); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.TableNameLength < 0 || value.TableNameLength > 128 {
				return false
			}
			if !w.putLebPair(uint64(value.TableNameLength)) {
				w.putLebWide(uint64(value.TableNameLength))
			}
			w.Raw(value.TableName[:value.TableNameLength])
		}
	}
	{
		if value.NameLength < 0 || value.NameLength > 128 {
			return false
		}
		if value.NameLength > 0 {
			if ref := w.Ids.refAtHit(120, 0xc4bcadba8e631b86); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.NameLength < 0 || value.NameLength > 128 {
				return false
			}
			if !w.putLebPair(uint64(value.NameLength)) {
				w.putLebWide(uint64(value.NameLength))
			}
			w.Raw(value.Name[:value.NameLength])
		}
	}
	{
		if value.ValueLength < 0 || value.ValueLength > 1024 {
			return false
		}
		if value.ValueLength > 0 {
			if ref := w.Ids.refAtHit(77, 0x7ce4fd9430e80cea); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.ValueLength < 0 || value.ValueLength > 1024 {
				return false
			}
			if !w.putLebPair(uint64(value.ValueLength)) {
				w.putLebWide(uint64(value.ValueLength))
			}
			w.Raw(value.Value[:value.ValueLength])
		}
	}
	{
		if value.WasLength < 0 || value.WasLength > 1024 {
			return false
		}
		if value.WasLength > 0 {
			if ref := w.Ids.refAtHit(59, 0x5eade819487cb532); !w.headerPair(ref, 12) {
				w.headerRest(ref, 12)
			}
			if value.WasLength < 0 || value.WasLength > 1024 {
				return false
			}
			if !w.putLebPair(uint64(value.WasLength)) {
				w.putLebWide(uint64(value.WasLength))
			}
			w.Raw(value.Was[:value.WasLength])
		}
	}
	{
		if value.WasAbsent != false {
			if ref := w.Ids.refAtHit(37, 0x32e6b0c4205a213e); !w.headerPair(ref, 1) {
				w.headerRest(ref, 1)
			}
			if value.WasAbsent {
				w.Put8(1)
			} else {
				w.Put8(0)
			}
		}
	}
	if !tableRetainTail(w) {
		return false
	}
	return !w.Overflow && !w.Ids.Overflow
}

