func TableCountLoadMessageBody(r *TableMessageReader, value *TableCount) bool {
	TableCountReset(value)
	for {
		ref, ok := r.Bits.Get(r.Vocabulary.RefBits)
		if !ok {
			r.Report.Malformed = true
			return false
		}
		if ref == 0 {
			return true
		}
		entry, ok := r.Vocabulary.Entry(ref)
		if !ok || entry.Id >= 0xfffffffffffffffd {
			r.Report.Malformed = true
			return false
		}
		switch entry.Id {
		case 0xc4bcadba8e631b86:
			{
				widened := false
				if entry.Shape.Kind != 12 || entry.Element.Kind != 0 {
					if false {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					n, ok := tableMessageCount(&r.Bits, entry.Shape)
					if !ok || !r.Bits.Align() {
						r.Report.Malformed = true
						return false
					}
					start := r.Bits.Offset / 8
					if !r.Bits.Skip(int64(n) * 8) {
						r.Report.Malformed = true
						return false
					}
					text := r.Bits.Buffer[start : start+int64(n)]
					if !tableUtf8Valid(text) {
						r.Report.Malformed = true
						return false
					}
					kept := tableUtf8Clamp(text, min(int64(n), int64(128)))
					if kept < int64(n) {
						r.Report.Clamped++
					}
					clear(value.Name[:])
					copy(value.Name[:], text[:kept])
					value.NameLength = int32(kept)
				}
				if widened {
					r.Report.Widened++
				}
			}
		case 0xb1e5e28e4479a274:
			{
				widened := false
				if entry.Shape.Kind != 4 || entry.Element.Kind != 0 {
					if entry.Element.Kind == 0 && tableKindWidens(entry.Shape.Kind, 4) {
						widened = true
					} else {
						r.Report.KindMismatch++
						if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
							r.Report.Malformed = true
							return false
						}
						break
					}
				}
				{
					var raw [16]byte
					if !tableMessageReadScalar(&r.Bits, entry.Shape, &raw) {
						r.Report.Malformed = true
						return false
					}
					payload107 := TableReader{Buffer: raw[:], Report: &r.Report}
					if !payload107.Has(tableKindBytes(entry.Shape.Kind)) {
						r.Report.Malformed = true
						return false
					}
					{
						v := payload107.Signed(entry.Shape.Kind)
						value.Count = int32(v)
					}
				}
				if widened {
					r.Report.Widened++
				}
			}
		default:
			r.Report.Unknown++
			if !tableMessageSkip(&r.Bits, r.Vocabulary, r.IndexBits, entry, 0) {
				r.Report.Malformed = true
				return false
			}
		}
	}
}
func TableCountLoadMessages(values []TableCount, vocabulary *TableVocabulary, data []byte, report *TableReport) (int64, bool) {
	if report == nil {
		var ignored TableReport
		report = &ignored
	}
	r, count := tableMessageBatchOpen(vocabulary, data, report)
	defer func() { *report = r.Report }()
	if count < 0 {
		return 0, false
	}
	if count > int64(len(values)) {
		return count, tableMessageRefuse(&r.Report, "batch_too_large")
	}
	for i := int64(0); i < count; i++ {
		if !TableCountLoadMessageBody(&r, &values[i]) {
			return i, false
		}
	}
	return count, tableMessageBatchClose(&r)
}

// StepResultReset restores StepResult's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func StepResultReset(value *StepResult) {
	clear(value.Verb[:])
	value.VerbLength = 0
	clear(value.Op[:])
	value.OpLength = 0
	for i := range value.Moved {
		Name256Reset(&value.Moved[i])
	}
	value.MovedCount = 0
	for i := range value.Refused {
		RefusalReset(&value.Refused[i])
	}
	value.RefusedCount = 0
	value.Notes = 0
	for i := range value.Raised {
		Name256Reset(&value.Raised[i])
	}
	value.RaisedCount = 0
	for i := range value.Said {
		Text512Reset(&value.Said[i])
	}
	value.SaidCount = 0
	value.Attempts = 0
	value.Replay = false
	for i := range value.Repaired {
		Name256Reset(&value.Repaired[i])
	}
	value.RepairedCount = 0
	clear(value.Pending[:])
	value.PendingLength = 0
	for i := range value.Skipped {
		Text512Reset(&value.Skipped[i])
	}
	value.SkippedCount = 0
	clear(value.Args[:])
	value.ArgsLength = 0
	value.Lost = false
	for i := range value.Tables {
		TableCountReset(&value.Tables[i])
	}
	value.TablesCount = 0
	value.Drained = 0
}

func StepResultMeasureBody(value *StepResult, ids *TableIds) int64 {
	w := TableWriter{Measuring: true, Ids: ids}
	if !StepResultSaveBody(&w, value) {
		return -1
	}
	return w.Offset
}

func StepResultSaveBody(w *TableWriter, value *StepResult) bool {
	if !StepResultSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
